"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["2843"],{2146:function(s,a,n){n.r(a),n.d(a,{default:function(){return p}});var t=n(1147);let l=["innerHTML"],p={setup:()=>({html:""}),render:()=>((0,t.wg)(),(0,t.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>结果反馈页</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>结果反馈页适合提交成功、支付结果、权限受限、网络异常等需要明确告知状态和下一步动作的移动业务页面。</p>\n<p>该场景使用 <code>NavBar</code>、<code>Empty</code>、<code>NoticeBar</code>、<code>CellGroup</code>、<code>Cell</code>、<code>Button</code> 和 <code>ActionBar</code> 组合出一个提交完成页面，包含结果说明、补充提示、关键记录和底部操作区。</p>\n</div><div class="mi-doc-card"><h3 id="tui-jian-zu-jian" tabindex="-1">推荐组件</h3>\n<table>\n<thead>\n<tr>\n<th>组件</th>\n<th>作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Empty</td>\n<td>结果态主体</td>\n</tr>\n<tr>\n<td>NoticeBar</td>\n<td>补充说明</td>\n</tr>\n<tr>\n<td>CellGroup</td>\n<td>展示关键记录</td>\n</tr>\n<tr>\n<td>Button</td>\n<td>页面内主动作</td>\n</tr>\n<tr>\n<td>ActionBar</td>\n<td>底部固定动作</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="shi-li-dai-ma" tabindex="-1">示例代码</h3>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-nav-bar</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;提交结果&quot;</span> <span class="hljs-attr">left-arrow</span> <span class="hljs-attr">left-text</span>=<span class="hljs-string">&quot;返回&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-empty</span> <span class="hljs-attr">image</span>=<span class="hljs-string">&quot;success&quot;</span> <span class="hljs-attr">description</span>=<span class="hljs-string">&quot;资料已提交，审核结果会通过短信通知&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-button</span> <span class="hljs-attr">round</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;primary&quot;</span>&gt;</span>返回列表<span class="hljs-tag">&lt;/<span class="hljs-name">mi-button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-empty</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-notice-bar</span>\n    <span class="hljs-attr">left-icon</span>=<span class="hljs-string">&quot;info-o&quot;</span>\n    <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;预计 1 个工作日内完成审核，请保持手机号可接收短信&quot;</span>\n/&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-cell-group</span> <span class="hljs-attr">inset</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;提交信息&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;业务编号&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;APPLY-2026050301&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;提交时间&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;2026-05-03 09:30&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;当前状态&quot;</span> <span class="hljs-attr">value</span>=<span class="hljs-string">&quot;审核中&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell-group</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-action-bar</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-action-bar-icon</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;records-o&quot;</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;记录&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-action-bar-icon</span> <span class="hljs-attr">icon</span>=<span class="hljs-string">&quot;service-o&quot;</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;客服&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-action-bar-button</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;primary&quot;</span> <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;继续提交&quot;</span> @<span class="hljs-attr">click</span>=<span class="hljs-string">&quot;onPrimary&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-action-bar</span>&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="gua-yong-chang-jing" tabindex="-1">适用场景</h3>\n<ul>\n<li>审核资料提交成功、预约成功、支付结果</li>\n<li>权限受限、网络异常、业务办理失败</li>\n<li>需要给用户明确下一步动作的结果页</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="shi-yong-jian-yi" tabindex="-1">使用建议</h3>\n<ul>\n<li>结果标题直接说明状态，不要只写“提示”。</li>\n<li>补充说明用于告知通知方式、预计处理时间或失败原因。</li>\n<li>保留一个主动作和一个次动作，避免结果页操作分散。</li>\n</ul>\n</div>'},null,8,l))}}}]);